// 3. Vector operations
var field_stations = ee.FeatureCollection([Heron,Lizard,Daydream,Orpheus,CoralBay,Moorea,CARMABI,Kimberly])
print (field_stations)
Map.addLayer(field_stations,{color:'yellow'})

// ACA operations
// Example mask application.
//var reef = CoralMap.select('reef_mask').selfMask();
//Map.addLayer(reef, {}, 'Global reef extent');

// Benthic habitat classification.
//var benthicHabitat = CoralMap.select('benthic').selfMask();
//Map.addLayer(benthicHabitat, {}, 'Benthic habitat');

//class 15 is coral

var coralAlgea = CoralMap.eq(15).selfMask()
Map.addLayer (coralAlgea, {palette:['#ff6161']},'Coral/Algea')

// make buffer 
var makeBuffered=function(feature){
  var buffered = feature.buffer(800)
  return buffered;
};

// use .map to work one station at a time 
var bufferedStation = field_stations.map(makeBuffered);
print (bufferedStation, 'buffered')
Map.addLayer(bufferedStation,{color:'yellow'}, 'buffered')

// compute area of coral within buffer
var coral_area = coralAlgea // binary 1 == coral
  .multiply(ee.Image.pixelArea()) // get the area of each pixel
  .reduceRegions({
  reducer:ee.Reducer.sum(), //sum all pixel areas together 
  collection:bufferedStation,
  scale:5});
  
// sort by sum, largest first
var sorted = coral_area.sort('sum', false);
print(sorted);

